package com.kartgarden.live.protocol;

import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.*;
import java.util.Arrays;

public class ProtocolTest {
    private byte[] start(int seq,int expected,byte[] chunk){byte[] p=new byte[24+chunk.length+8];p[3]=(byte)(seq>>8);p[4]=(byte)seq;p[12]=8;System.arraycopy(new byte[]{'F','R','A','M'},0,p,13,4);ByteBuffer.wrap(p).putInt(17,expected+38);System.arraycopy(chunk,0,p,24,chunk.length);return p;}
    private byte[] continuation(int seq,int kind,byte[] chunk){int skip=kind==0x85?1:5;byte[] p=new byte[12+skip+chunk.length+8];p[3]=(byte)(seq>>8);p[4]=(byte)seq;p[11]=(byte)kind;p[12]=0x72;for(int i=1;i<skip;i++)p[12+i]=(byte)0xef;System.arraycopy(chunk,0,p,12+skip,chunk.length);return p;}
    @Test public void assemblesTerminalWithoutMetadata(){LspAssembler a=new LspAssembler();byte[] first={0,0,0,1,0x65,1};assertNull(a.feed(start(1,10,first)));LspAssembler.Frame f=a.feed(continuation(2,0xb6,new byte[]{2,3,4,5}));assertNotNull(f);assertFalse(f.damaged());assertArrayEquals(new byte[]{0,0,0,1,0x65,1,2,3,4,5},f.annexB());}
    @Test public void allTerminalKindsSkipFourExtraBytes(){for(int kind:new int[]{0xb6,0xba,0xbe}){LspAssembler a=new LspAssembler();a.feed(start(0,8,new byte[]{0,0,0,1,0x65}));assertArrayEquals(new byte[]{0,0,0,1,0x65,4,5,6},a.feed(continuation(1,kind,new byte[]{4,5,6})).annexB());}}
    @Test public void gapsMarkFrameDamaged(){LspAssembler a=new LspAssembler();a.feed(start(5,8,new byte[]{0,0,0,1,0x65}));assertTrue(a.feed(continuation(7,0x85,new byte[]{1,2,3})).damaged());assertEquals(1,a.gaps);}
    @Test public void duplicatesLateAndWrap(){LspAssembler a=new LspAssembler();byte[] p=start(65535,5,new byte[]{0,0,0,1,0x65});assertNotNull(a.feed(p));assertNull(a.feed(p));assertNotNull(a.feed(start(0,5,new byte[]{0,0,0,1,0x65})));assertNull(a.feed(start(65534,5,new byte[]{0,0,0,1,0x65})));assertEquals(0,a.gaps);assertEquals(2,a.frames);}
    @Test public void newFrameAbandonsIncomplete(){LspAssembler a=new LspAssembler();a.feed(start(1,10,new byte[]{0,0,0,1,0x65}));assertNotNull(a.feed(start(2,5,new byte[]{0,0,0,1,0x65})));assertEquals(1,a.abandoned);}
    @Test public void malformedVideoAndNalSplitting(){LspAssembler a=new LspAssembler();for(int n=0;n<28;n++)assertNull(a.feed(new byte[n]));assertEquals(2,LspAssembler.nals(new byte[]{0,0,1,0x67,5,0,0,0,1,0x68,3}).size());assertEquals(2,LspAssembler.accessUnits(new byte[]{0,0,1,9,0,0,1,0x65,0,0,1,9,0,0,1,0x41}).size());}
    private byte[] imu(int samples){byte[] p=new byte[73+12*samples];p[0]=2;p[3]=(byte)(0x60|(samples-1));ByteBuffer b=ByteBuffer.wrap(p).order(ByteOrder.LITTLE_ENDIAN);b.putInt(21,1073741824);for(int i=0;i<samples;i++){b.putShort(73+12*i,(short)(100+i));b.putShort(79+12*i,(short)-200);}return p;}
    @Test public void decodesAllSubsamplesAndSignedGyro(){Telemetry t=Telemetry.parse(imu(8));assertTrue(t.valid);assertEquals(8,t.samples.size());assertEquals(107,t.latest().accelRaw()[0]);assertEquals(-.875,t.latest().gyro()[0],1e-10);assertArrayEquals(new double[]{0,0,0,1},t.quaternion,1e-10);}
    @Test public void rejectsShortImuAndInvalidQuaternion(){byte[] p=imu(8);assertFalse(Telemetry.parse(Arrays.copyOf(p,85)).valid);ByteBuffer.wrap(p).order(ByteOrder.LITTLE_ENDIAN).putInt(21,0);assertNull(Telemetry.parse(p).quaternion);}
    @Test public void batteryIsHudBarsNotPercent(){Telemetry t=Telemetry.parse(new byte[]{1,1,0,0,4});assertTrue(t.valid);assertEquals(4,t.battery);assertTrue(t.cable);assertFalse(Telemetry.parse(new byte[]{1,0,0,0,5}).valid);}
    @Test public void motorLayoutCountersAndExhaustion(){MotorLease l=new MotorLease();l.arm(0xfffffffeL,2);byte[] p=l.packet(-1,1);assertEquals(127,p[0]);assertEquals(-127,p[1]);assertEquals(0xfffffffeL,ByteBuffer.wrap(p).order(ByteOrder.LITTLE_ENDIAN).getInt(4)&0xffffffffL);for(int i=8;i<32;i++)assertEquals(0,p[i]);assertNotNull(l.packet(0,0));assertNull(l.packet(0,0));}
    @Test public void rejectsCounterOverflow(){MotorLease l=new MotorLease();assertThrows(IllegalArgumentException.class,()->l.arm(0xffffffffL,2));assertThrows(IllegalArgumentException.class,()->l.arm(-1,1));assertThrows(IllegalArgumentException.class,()->l.arm(1,0));}
    @Test public void shutdownAndNonfiniteCannotMove(){MotorLease l=new MotorLease();l.arm(1,100);l.clear();assertNull(l.packet(1,1));l.arm(1,100);assertNull(l.packet(Float.NaN,1));assertFalse(l.active());}
    @Test public void watchdogRejectsBackgroundStaleAndFrozenInput(){assertTrue(MotorLease.safe(true,true,30,0,0,99999));assertFalse(MotorLease.safe(false,true,30,0,0,0));assertFalse(MotorLease.safe(true,false,30,0,0,0));assertFalse(MotorLease.safe(true,true,1000,0,0,0));assertFalse(MotorLease.safe(true,true,30,1,0,501));assertFalse(MotorLease.safe(true,true,30,Float.NaN,0,0));}
    @Test public void parsesDashboardEnrollmentUrlAndNestedAliases() throws Exception {ClientConfig c=ClientConfig.parse("{\"client\":{\"client_key\":\"example-placeholder\",\"permission\":\"CONTROL\"},\"api_url\":\"https://pi.local:9443\"}");assertEquals("control",c.permission());assertEquals("pi.local",c.host());assertEquals(9443,c.port());}
    @Test public void invalidCredentialsFailClosed(){assertThrows(Exception.class,()->ClientConfig.parse("{}"));assertThrows(Exception.class,()->ClientConfig.parse("{\"key\":\"placeholder\",\"permission\":\"admin\"}"));assertThrows(Exception.class,()->ClientConfig.parse("{\"key\":\"placeholder\",\"api_url\":\"http://pi.local\"}"));}
    @Test public void quaternionIntegrationAndReset(){double[] q=Orientation.integrate(Orientation.identity(),new double[]{0,0,90},1);assertEquals(Math.sqrt(.5),q[2],1e-9);assertArrayEquals(Orientation.identity(),Orientation.multiply(Orientation.inverse(q),q),1e-9);Orientation o=new Orientation();o.calibrate();o.reset();assertFalse(o.calibrated());}
}
